// Generated root index. Deliberately a JS template, not markdown: its job
// is to compute a redirect from whatever locales actually exist on disk,
// not to hold authored content, so it shouldn't tempt anyone into editing
// prose here later. Lives at content/index.11ty.js, outside every locale
// folder — same reasoning as before, it stays invisible to the
// locale/nav/language-switcher collections, which all key off `locale`.
const siteConfig = require("../_11ty/site-config.js");

module.exports = class {
  data() {
    return {
      eleventyExcludeFromCollections: true,
      layout: false,
    };
  }

  render(data) {
    const byLocale = data.collections.byLocale || {};
    const locales = Object.keys(byLocale).sort();

    const label = (locale) => {
      const page = byLocale[locale][0];
      return (page && page.data.localeLabel) || locale;
    };

    // Same default-locale config the <head> partial uses for x-default,
    // so "the fallback locale" means one thing sitewide. Only matters
    // here when JS is off or no browser language matches any available
    // locale's primary subtag.
    const fallback = locales.includes(siteConfig.defaultLocale)
      ? siteConfig.defaultLocale
      : locales[0];

    const links = locales
      .map((locale) => `<a href="/${locale}/">${label(locale)}</a>`)
      .join(" · ");

    return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Vishpala</title>
  <meta http-equiv="refresh" content="0; url=/${fallback}/">
  <link rel="canonical" href="/${fallback}/">
  <script>
    // Matches each available locale's primary language subtag
    // ("fr-ca" -> "fr") against the browser's preferred languages, in
    // order, and redirects to the first match. Falls back to the
    // meta-refresh above if nothing matches or JS is unavailable.
    var locales = ${JSON.stringify(locales)};
    var fallback = ${JSON.stringify(fallback)};
    var browserLangs = (navigator.languages || [navigator.language || fallback])
      .map(function (l) { return l.toLowerCase(); });

    var match = browserLangs
      .map(function (lang) {
        var primary = lang.split("-")[0];
        return locales.find(function (locale) {
          return locale.split("-")[0] === primary;
        });
      })
      .find(Boolean);

    location.replace("/" + (match || fallback) + "/");
  </script>
</head>
<body>
  <p>Redirecting… if nothing happens, choose a language: ${links}</p>
</body>
</html>
`;
  }
};

const UUID_RE = /^urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * @param {Array} pages Eleventy page objects (already filtered to
 *   locale-bearing content pages).
 * @returns {{ errors: string[], warnings: string[] }}
 */
function validateContent(pages) {
  const errors = [];
  const warnings = [];

  // ---- identifier: must be a well-formed urn:uuid, and unique ----
  const byIdentifier = new Map();
  for (const p of pages) {
    if (!p.data.identifier) continue;
    if (!UUID_RE.test(p.data.identifier)) {
      errors.push(
        `${p.inputPath}: identifier "${p.data.identifier}" is not a well-formed urn:uuid.`
      );
    }
    const list = byIdentifier.get(p.data.identifier) || [];
    list.push(p.inputPath);
    byIdentifier.set(p.data.identifier, list);
  }
  for (const [id, paths] of byIdentifier) {
    if (paths.length > 1) {
      errors.push(`identifier ${id} is used by more than one file: ${paths.join(", ")}`);
    }
  }

  // ---- relation: must be well-formed, and its group of pages checked ----
  // ---- for the two failure modes that break translation pairing     ----
  const byRelation = new Map();
  for (const p of pages) {
    if (!p.data.relation) continue;
    if (!UUID_RE.test(p.data.relation)) {
      errors.push(
        `${p.inputPath}: relation "${p.data.relation}" is not a well-formed urn:uuid.`
      );
    }
    const list = byRelation.get(p.data.relation) || [];
    list.push(p);
    byRelation.set(p.data.relation, list);
  }
  for (const [rel, group] of byRelation) {
    const byLocaleCount = new Map();
    for (const p of group) {
      byLocaleCount.set(p.data.locale, (byLocaleCount.get(p.data.locale) || 0) + 1);
    }
    for (const [loc, count] of byLocaleCount) {
      if (count > 1) {
        const paths = group
          .filter((p) => p.data.locale === loc)
          .map((p) => p.inputPath)
          .join(", ");
        warnings.push(
          `relation ${rel} has ${count} pages in the same locale "${loc}" (${paths}) — ` +
            `two Expressions of one Work in the same locale is unusual; check this is intentional.`
        );
      }
    }
    if (group.length === 1 && !group[0].data.localeExclusive) {
      warnings.push(
        `relation ${rel} only exists in locale "${group[0].data.locale}" ` +
          `(${group[0].inputPath}). If a translation is on the way, ignore this. If it's ` +
          `never getting one, add "localeExclusive: true" to its front matter to silence ` +
          `this warning — otherwise this usually means a typo broke the pairing on the ` +
          `missing locale's page.`
      );
    }
  }

  // ---- description: warn (non-fatal) when a page has no dc:description ----
  for (const p of pages) {
    if (!p.data.description || !String(p.data.description).trim()) {
      warnings.push(
        `${p.inputPath}: no dc:description set — every page should have a short summary for search results and screen readers.`
      );
    }
  }

  return { errors, warnings };
}

module.exports = { validateContent, UUID_RE };
