"""Static accessibility and link checks over a built Eleventy site.

Usage: python3 -I check_site.py <built-site-dir>
Exits 1 if any check fails.
"""
import sys
from collections import Counter
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlsplit, unquote

SITE = Path(sys.argv[1])
SKIP = ("pagefind/", "admin/")


class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.html_attrs = {}
        self.links = []
        self.imgs = []
        self.headings = []
        self.ids = []
        self.switcher = []
        self.in_switcher = 0
        self.notice = False
        self.main = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "html":
            self.html_attrs = a
        if "id" in a:
            self.ids.append(a["id"])
        if tag == "main" and a.get("id") == "main":
            self.main = True
        if tag in ("a", "link") and a.get("href"):
            self.links.append((tag, a.get("rel", ""), a["href"]))
        if tag in ("img", "script") and a.get("src"):
            self.links.append((tag, "", a["src"]))
        if tag == "img":
            self.imgs.append(a)
        if tag in ("h1", "h2", "h3", "h4", "h5", "h6"):
            self.headings.append(int(tag[1]))
        if tag == "ul" and "language-switcher" in a.get("class", "").split():
            self.in_switcher = 1
        elif self.in_switcher and tag == "a":
            self.switcher.append(a)
        if tag == "p" and "translation-notice" in a.get("class", ""):
            self.notice = True

    def handle_endtag(self, tag):
        if tag == "ul" and self.in_switcher:
            self.in_switcher = 0


def resolve(page_path, url):
    parts = urlsplit(url)
    if parts.scheme or parts.netloc or url.startswith(("mailto:", "#", "tel:")):
        return None
    path = unquote(parts.path)
    if not path:
        return None
    target = SITE / path.lstrip("/") if path.startswith("/") else page_path.parent / path
    if path.endswith("/"):
        target = target / "index.html"
    return target


problems = []
pages = [p for p in sorted(SITE.rglob("*.html")) if not str(p.relative_to(SITE)).startswith(SKIP)]
locales = sorted(d.name for d in SITE.iterdir() if d.is_dir() and d.name.endswith("-ca"))
for path in pages:
    rel = path.relative_to(SITE)
    pg = Page()
    pg.feed(path.read_text(encoding="utf-8"))
    loc = rel.parts[0] if len(rel.parts) > 1 else None
    if not pg.html_attrs.get("lang"):
        problems.append(f"{rel}: <html> has no lang")
    if loc and pg.html_attrs.get("dir") not in ("ltr", "rtl"):
        problems.append(f"{rel}: <html> has no dir")
    if loc and pg.html_attrs.get("lang", "").lower() != loc:
        problems.append(f"{rel}: lang {pg.html_attrs.get('lang')} does not match folder {loc}")
    for tag, relattr, url in pg.links:
        if relattr in ("canonical", "alternate"):
            continue
        target = resolve(path, url)
        if target is not None and not target.exists():
            problems.append(f"{rel}: broken {tag} -> {url}")
    for img in pg.imgs:
        if "alt" not in img:
            problems.append(f"{rel}: img without alt: {img.get('src')}")
    if not loc:
        continue
    if pg.headings.count(1) != 1:
        problems.append(f"{rel}: {pg.headings.count(1)} h1 elements")
    for prev, cur in zip(pg.headings, pg.headings[1:]):
        if cur > prev + 1:
            problems.append(f"{rel}: heading jumps h{prev} -> h{cur}")
            break
    dup = [i for i, n in Counter(pg.ids).items() if n > 1]
    if dup:
        problems.append(f"{rel}: duplicate ids {dup}")
    if not pg.main:
        problems.append(f"{rel}: no <main id=main> for the skip link")
    if pg.switcher:
        if len(pg.switcher) != len(locales) and "press" not in rel.parts:
            problems.append(f"{rel}: switcher lists {len(pg.switcher)} languages, site has {len(locales)}")
        for a in pg.switcher:
            if not (a.get("hreflang")):
                problems.append(f"{rel}: switcher link without hreflang: {a.get('href')}")
        current = [a for a in pg.switcher if a.get("aria-current") == "page"]
        if len(current) != 1:
            problems.append(f"{rel}: {len(current)} switcher links marked aria-current=page")
    if loc == "es-ca" and not pg.notice:
        problems.append(f"{rel}: es-ca page without the review notice")
    if loc != "es-ca" and pg.notice:
        problems.append(f"{rel}: review notice on a non-es-ca page")

print(f"checked {len(pages)} pages in {len(locales)} locales: {', '.join(locales)}")
for p in problems:
    print("FAIL", p)
print(f"{len(problems)} problem(s)")
sys.exit(1 if problems else 0)

